import { resourceUrl } from './electron';
import { getConfig } from './config';

// resources/languages/<locale>.js defines a global `locale` map (generated by languages.js)
export function loadLocale(): Promise<void> {
	return new Promise((resolve) => {
		const script = document.createElement('script');
		script.src = resourceUrl('languages/' + (getConfig().locale || 'en') + '.js');
		script.onload = () => resolve();
		script.onerror = () => {
			console.error('Could not load locale', script.src);
			resolve();
		};
		document.head.appendChild(script);
	});
}

export function t(key: string): string {
	const locale = (window as Window).locale;
	return (locale && locale[key]) || key;
}

// Replaces {0}, {1}... like Ext.String.format
export function format(text: string, ...args: (string | number)[]): string {
	return text.replace(/\{(\d+)\}/g, (match, i) => (args[i] !== undefined ? String(args[i]) : match));
}
